/bin/zsh -lc "set -e
awk '
  /"'^[[:space:]]*$/ { next }
  !/''^[A-Za-z0-9_]+'"\\[[0-9]+\\]=[A-Za-z0-9_-]+"'$/ { print "Invalid lab.conf syntax at line " NR ": " $0; bad=1 }
  { split($0, a, "="); if (a[2] ~ /'"\\\"/) { print \"Quoted collision domain at line \" NR; bad=1 } }
  END { exit bad }
' output/lab/lab.conf
awk -F= '
  NF == 2 && "'$1 !~ /''^[[:space:]]*$/ { count[$2]++ }
  END { for (domain in count) if (count[domain] < 2) { print "Unpaired collision domain: " domain; bad=1 } exit bad }
'"' output/lab/lab.conf
for router in R1 R2 R3 R4 R5; do
  test -f \"output/lab/"'${router}.startup"
  ! rg -q '"'("'^|[[:space:]])(default|0'"\\.0\\.0\\.0/0)([[:space:]]|"'$)'"' \"output/lab/"'${router}.startup"
done
rg -n '"'\"|default|0\\.0\\.0\\.0/0' output/lab/lab.conf output/lab/R*.startup || true
git diff --check -- output/lab/lab.conf
git diff -- output/lab/lab.conf"

